export const COLORS = {
  RED: 'bg-red-500',
  GREEN: 'bg-emerald-500',
  BLUE: 'bg-blue-500',
  GOLD: 'bg-amber-500',
  SPECIAL: 'bg-purple-600'
};

export const getNumberColor = (num: number): string => {
  if (num <= 10) return COLORS.RED;
  if (num <= 20) return COLORS.BLUE;
  if (num <= 30) return COLORS.GREEN;
  if (num <= 40) return COLORS.GOLD;
  return 'bg-slate-500';
};

import { GoogleGenAI, Type } from "@google/genai";
import { DrawResult, PredictionResult } from "./types";

export const getAIPrediction = async (history: DrawResult[]): Promise<PredictionResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const historyString = history.map(h => 
    `Draw ${h.drawNumber}: ${h.numbers.join(', ')} | Special: ${h.specialNumber}`
  ).join('\n');

  const prompt = `
    As a statistical analyst for the Mark Six lottery (49 numbers), analyze the following recent draw history:
    ${historyString}

    Based on your analysis of frequency, "hot" and "cold" numbers, and distribution patterns, generate a set of predicted numbers for the next draw.
    Provide 6 main numbers (1-49) and 1 special number (1-49).
    Also provide a confidence score (0-100) and a brief reasoning for these choices.

    IMPORTANT: Acknowledge that lottery results are fundamentally random and this is for entertainment purposes based on historical patterns.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            numbers: {
              type: Type.ARRAY,
              items: { type: Type.INTEGER },
              description: "Array of 6 unique integers between 1 and 49"
            },
            specialNumber: {
              type: Type.INTEGER,
              description: "A special integer between 1 and 49"
            },
            confidence: {
              type: Type.INTEGER,
              description: "Confidence score out of 100"
            },
            reasoning: {
              type: Type.STRING,
              description: "Brief statistical reasoning"
            }
          },
          required: ["numbers", "specialNumber", "confidence", "reasoning"]
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    return {
      numbers: result.numbers.sort((a: number, b: number) => a - b),
      specialNumber: result.specialNumber,
      confidence: result.confidence,
      reasoning: result.reasoning
    };
  } catch (error) {
    console.error("Gemini Prediction Error:", error);
    // Fallback pseudo-random prediction if API fails
    const randomNums = Array.from({length: 49}, (_, i) => i + 1)
      .sort(() => Math.random() - 0.5)
      .slice(0, 6)
      .sort((a, b) => a - b);

    return {
      numbers: randomNums,
      specialNumber: Math.floor(Math.random() * 49) + 1,
      confidence: 15,
      reasoning: "The AI analyst is currently unavailable. This is a baseline statistical sample based on uniform distribution."
    };
  }
};

import React from 'react';
import { getNumberColor } from '../constants';

interface BallProps {
  number: number;
  isSpecial?: boolean;
  size?: 'sm' | 'md' | 'lg';
}

const Ball: React.FC<BallProps> = ({ number, isSpecial = false, size = 'md' }) => {
  const sizeClasses = {
    sm: 'w-8 h-8 text-sm',
    md: 'w-12 h-12 text-lg',
    lg: 'w-16 h-16 text-2xl font-bold'
  };

  const baseColor = isSpecial ? 'bg-purple-600' : getNumberColor(number);

  return (
    <div className={`${sizeClasses[size]} ${baseColor} rounded-full flex items-center justify-center text-white shadow-xl lottery-ball transform transition-transform hover:scale-110 cursor-default border-t border-white/20`}>
      {number}
    </div>
  );
};

export default Ball;

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { DrawResult, NumberFrequency } from '../types';
import { getNumberColor } from '../constants';

interface FrequencyChartProps {
  history: DrawResult[];
}

const FrequencyChart: React.FC<FrequencyChartProps> = ({ history }) => {
  const calculateFrequency = (): NumberFrequency[] => {
    const counts: Record<number, number> = {};
    history.forEach(draw => {
      [...draw.numbers, draw.specialNumber].forEach(num => {
        counts[num] = (counts[num] || 0) + 1;
      });
    });

    return Object.entries(counts)
      .map(([num, count]) => ({ number: parseInt(num), count }))
      .sort((a, b) => a.number - b.number);
  };

  const data = calculateFrequency();

  return (
    <div className="h-[400px] w-full mt-6">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart data={data}>
          <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
          <XAxis 
            dataKey="number" 
            stroke="#94a3b8" 
            fontSize={12}
            tick={{ fill: '#94a3b8' }}
          />
          <YAxis stroke="#94a3b8" fontSize={12} tick={{ fill: '#94a3b8' }} />
          <Tooltip 
            contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #334155', borderRadius: '8px' }}
            itemStyle={{ color: '#f8fafc' }}
          />
          <Bar dataKey="count" radius={[4, 4, 0, 0]}>
            {data.map((entry, index) => (
              <Cell key={`cell-${index}`} className={getNumberColor(entry.number).replace('bg-', 'fill-')} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

export default FrequencyChart;

