import { GoogleGenAI, Type } from "@google/genai";

interface DrawResult {
  drawNumber: string;
  numbers: number[];
  specialNumber: number;
}

export async function onRequestPost(context: any) {
  try {
    const { history } = await context.request.json();
    const apiKey = context.env.API_KEY;

    if (!apiKey) {
      return new Response(JSON.stringify({ error: "API_KEY not configured" }), { 
        status: 500,
        headers: { "Content-Type": "application/json" }
      });
    }

    const ai = new GoogleGenAI({ apiKey });

    const historyString = history.map((h: DrawResult) => 
      `期号 ${h.drawNumber}: ${h.numbers.join(', ')} | 特码: ${h.specialNumber}`
    ).join('\n');

    const prompt = `
      作为一名六合彩（49个号码）统计分析师，请分析以下近期开奖记录：
      ${historyString}

      基于频率、冷热号和分布模式的分析，生成下一期的预测号码。

      请提供：
      1. 6个正码（1-49，不重复）
      2. 1个特码（1-49）
      3. 信心指数（0-100）
      4. 简短的推荐理由（使用中文，解释为什么选择这些号码，例如基于走势、遗漏或热号回补等）

      重要提示：必须承认彩票结果基本是随机的，这仅基于历史模式的娱乐性分析。
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            numbers: {
              type: Type.ARRAY,
              items: { type: Type.INTEGER },
              description: "Array of 6 unique integers between 1 and 49"
            },
            specialNumber: {
              type: Type.INTEGER,
              description: "A special integer between 1 and 49"
            },
            confidence: {
              type: Type.INTEGER,
              description: "Confidence score out of 100"
            },
            reasoning: {
              type: Type.STRING,
              description: "Brief statistical reasoning in Chinese"
            }
          },
          required: ["numbers", "specialNumber", "confidence", "reasoning"]
        }
      }
    });

    const result = JSON.parse(response.text || '{}');

    // Ensure numbers are sorted
    if (result.numbers) {
      result.numbers.sort((a: number, b: number) => a - b);
    }

    return new Response(JSON.stringify(result), {
      headers: { "Content-Type": "application/json" }
    });

  } catch (error: any) {
    return new Response(JSON.stringify({ error: error.message }), {
      status: 500,
      headers: { "Content-Type": "application/json" }
    });
  }
}

import { DrawResult, PredictionResult } from "./types";

export const getAIPrediction = async (history: DrawResult[]): Promise<PredictionResult> => {
  try {
    const response = await fetch('/api/predict', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ history }),
    });

    if (!response.ok) {
      throw new Error(`API Error: ${response.status}`);
    }

    const result = await response.json();

    if (result.error) {
      throw new Error(result.error);
    }

    return {
      numbers: result.numbers,
      specialNumber: result.specialNumber,
      confidence: result.confidence,
      reasoning: result.reasoning
    };
  } catch (error) {
    console.error("Prediction Error:", error);

    // Fallback pseudo-random prediction if API/Network fails
    const randomNums = Array.from({length: 49}, (_, i) => i + 1)
      .sort(() => Math.random() - 0.5)
      .slice(0, 6)
      .sort((a, b) => a - b);

    return {
      numbers: randomNums,
      specialNumber: Math.floor(Math.random() * 49) + 1,
      confidence: 15,
      reasoning: "无法连接到 AI 分析服务。当前显示为基于随机分布的示例数据。(请确保项目已部署到 Cloudflare Pages 并配置 API_KEY)"
    };
  }
};

