import { GoogleGenAI, Type } from "@google/genai";

export async function onRequestPost(context: any) {
  try {
    const { apiUrl, lotteryName } = await context.request.json();
    const apiKey = context.env.API_KEY;

    if (!apiKey) {
      return new Response(JSON.stringify({ error: "Cloudflare 环境中未配置 API_KEY" }), { 
        status: 500,
        headers: { "Content-Type": "application/json" }
      });
    }

    // 1. Fetch live data from the provided URL
    const externalResponse = await fetch(apiUrl);
    if (!externalResponse.ok) {
      throw new Error(`无法从数据源获取数据: ${externalResponse.status}`);
    }
    const rawData = await externalResponse.json();

    // 2. Parse the specific JSON format provided by user
    // Format: { data: [{ expect: "...", openCode: "1,2,3,4,5,6,7", openTime: "..." }] }
    const historyData = (rawData.data || []).slice(0, 15).map((item: any) => {
      const codes = item.openCode.split(',').map((c: string) => parseInt(c.trim()));
      return {
        drawNumber: item.expect,
        date: item.openTime,
        numbers: codes.slice(0, 6),
        specialNumber: codes[6]
      };
    });

    if (historyData.length === 0) {
      throw new Error("未能成功解析开奖数据");
    }

    // 3. Prepare AI Prompt
    const ai = new GoogleGenAI({ apiKey });
    const historyString = historyData.map((h: any) => 
      `期号 ${h.drawNumber}: ${h.numbers.join(', ')} | 特码: ${h.specialNumber}`
    ).join('\n');

    const prompt = `
      你是一位专业的彩票分析大师。正在为 "${lotteryName}" 进行深度预测。

      以下是该彩种最近 ${historyData.length} 期的真实开奖数据：
      ${historyString}

      请基于概率学、号码走势、冷热平衡以及奇偶分布，预测下一期的号码。

      要求输出 JSON 格式：
      1. numbers: 6个正码 (1-49)
      2. specialNumber: 1个特码 (1-49)
      3. confidence: 信心指数 (0-100)
      4. reasoning: 详细的中文分析理由（包括选号逻辑、推荐胆码、遗漏参考等）

      提示：请务必声明彩票随机性，预测仅供参考。
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            numbers: { type: Type.ARRAY, items: { type: Type.INTEGER } },
            specialNumber: { type: Type.INTEGER },
            confidence: { type: Type.INTEGER },
            reasoning: { type: Type.STRING }
          },
          required: ["numbers", "specialNumber", "confidence", "reasoning"]
        }
      }
    });

    const prediction = JSON.parse(response.text || '{}');
    if (prediction.numbers) {
      prediction.numbers.sort((a: number, b: number) => a - b);
    }

    return new Response(JSON.stringify({
      prediction,
      history: historyData
    }), {
      headers: { "Content-Type": "application/json" }
    });

  } catch (error: any) {
    return new Response(JSON.stringify({ error: error.message }), {
      status: 500,
      headers: { "Content-Type": "application/json" }
    });
  }
}

import { DrawResult, PredictionResult, LotteryConfig } from "./types";

export const fetchLotteryDataAndPrediction = async (config: LotteryConfig): Promise<{ prediction: PredictionResult, history: DrawResult[] }> => {
  try {
    const response = await fetch('/api/predict', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ 
        apiUrl: config.apiUrl,
        lotteryName: config.name
      }),
    });

    if (!response.ok) {
      const errData = await response.json();
      throw new Error(errData.error || `服务器错误: ${response.status}`);
    }

    const data = await response.json();
    return data;
  } catch (error: any) {
    console.error("Prediction Error:", error);
    throw error;
  }
};

