import React, { useState, useEffect } from 'react';
import { DrawResult, PredictionResult, LotteryConfig } from './types';
import { LOTTERY_CONFIGS } from './constants';
import { fetchLotteryDataAndPrediction } from './geminiService';
import { LotteryTabs } from './components/LotteryTabs';
import { LatestDraw } from './components/LatestDraw';
import { PredictionCard } from './components/PredictionCard';
import { HistoryList } from './components/HistoryList';

// Add type definition for Telegram WebApp
declare global {
  interface Window {
    Telegram: {
      WebApp: {
        ready: () => void;
        expand: () => void;
        MainButton: any;
        ThemeParams: any;
      };
    };
  }
}

const App: React.FC = () => {
  const [selectedLottery, setSelectedLottery] = useState<LotteryConfig>(LOTTERY_CONFIGS[0]);
  const [history, setHistory] = useState<DrawResult[]>([]);
  const [prediction, setPrediction] = useState<PredictionResult | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  // Initialize Telegram Web App
  useEffect(() => {
    if (window.Telegram?.WebApp) {
      window.Telegram.WebApp.ready();
      window.Telegram.WebApp.expand();
    }
  }, []);

  // Reset state on lottery switch
  useEffect(() => {
    setPrediction(null);
    setHistory([]);
    setIsLoading(false);
  }, [selectedLottery]);

  const handlePredict = async () => {
    setIsLoading(true);
    try {
      const result = await fetchLotteryDataAndPrediction(selectedLottery);
      setPrediction(result.prediction);
      setHistory(result.history);
    } catch (err: any) {
      console.error(err);
      // In a real app, show a toast here. For now, simple alert or silence.
      alert("获取数据失败，请重试");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#0f172a]">
      {/* 1. Navigation Bar */}
      <LotteryTabs 
        configs={LOTTERY_CONFIGS}
        selected={selectedLottery}
        onSelect={setSelectedLottery}
      />

      {/* 2. Latest Draw Record (Top of Middle) */}
      <LatestDraw 
        draw={history.length > 0 ? history[0] : null} 
        isLoading={isLoading} 
      />

      {/* 3. Prediction Result (Middle) */}
      <PredictionCard 
        prediction={prediction}
        isLoading={isLoading}
        onPredict={handlePredict}
      />

      {/* 4. Prediction Record / Draw History (Bottom) */}
      <HistoryList history={history} />
    </div>
  );
};

export default App;

