const App: React.FC = () => {
  const [selectedLottery, setSelectedLottery] = useState<LotteryConfig>(LOTTERY_CONFIGS[0]);
  const [activeTab, setActiveTab] = useState<TabType>(TabType.PREDICT);

  const [history, setHistory] = useState<DrawResult[]>([]);
  const [prediction, setPrediction] = useState<PredictionResult | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (window.Telegram?.WebApp) {
      window.Telegram.WebApp.ready();
      window.Telegram.WebApp.expand();
    }
  }, []);

  const loadData = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const result = await fetchLotteryHistory(selectedLottery);
      setHistory(result.history);
      setPrediction(result.prediction);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "加载失败");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [selectedLottery]);

  const renderContent = () => {
    switch (activeTab) {
      case TabType.PREDICT:
        return (
          <>
            <LatestDraw draw={history[0]} isLoading={isLoading} />
            <div className="px-4 mt-6 pb-24">
              <PredictionPanel 
                prediction={prediction}
                isLoading={isLoading}
                error={error}
                onPredict={loadData} // 重新加载即重新预测
                lotteryName={selectedLottery.name}
              />
            </div>
          </>
        );
      case TabType.STATS:
        return (
          <div className="px-4 mt-6 pb-24">
            <StatisticsPanel history={history} />
          </div>
        );
      case TabType.HISTORY:
        return (
          <div className="px-4 mt-6 pb-24">
            <HistoryPanel history={history} lotteryName={selectedLottery.name} />
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-100 font-sans selection:bg-amber-500/30">
      <Header />

      <LotteryTabs 
        configs={LOTTERY_CONFIGS}
        selected={selectedLottery}
        onSelect={setSelectedLottery}
      />

      {renderContent()}

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

