          await doSyncAll(env, chatId);
          break;

      case '推送频道':
      case '/push':
          if (!isAdmin) {
             await sendMessage(env.TG_BOT_TOKEN, chatId, "⛔ 只有管理员可以使用推送功能");
             return;
          }
          await doPushAllToChannel(env, chatId);
          break;

      default:
          // 不回复默认消息，或者回复帮助信息
          // await sendHelpMessage(env.TG_BOT_TOKEN, chatId);
          break;
  }

  return new Response('OK');
}

