interface StrategyWeights {
    HOT: number;
    COLD: number;
    REPEAT: number;
    SYNERGY: number; // 属性协同系数 (乘法)
    description: string;
}

// ---------------------------------------------------------
// 增强型统计引擎：时间加权与条件概率
// ---------------------------------------------------------
class StatisticsEngine {
    history: any[];
    weightedFreq: Record<number, number> = {};
    zodiacWeight: Record<string, number> = {};
    colorWeight: Record<string, number> = {};
    tailWeight: Record<number, number> = {};

    // 条件概率矩阵：P(当前期号码 | 上期号码)
    transitionMatrix: Record<number, Record<number, number>> = {};

    constructor(history: any[]) {
        this.history = history;
        this.init();
    }

    private init() {
        for (let i = 1; i <= 49; i++) {
            this.weightedFreq[i] = 0;
            this.transitionMatrix[i] = {};
        }

        // 1. 时间加权频率统计 (Exponential Decay)
        this.history.forEach((draw, index) => {
            // 时间权重：近的期数权重极大
            const weight = Math.exp(-index / 15) * 2.0; 
            const sp = parseInt(draw.specialNumber);
            if (!isNaN(sp)) {
                this.weightedFreq[sp] += weight;

                // 属性加权
                const z = getZodiacForNumber(sp);
                this.zodiacWeight[z] = (this.zodiacWeight[z] || 0) + weight;
                const c = getColorForNumber(sp);
                this.colorWeight[c] = (this.colorWeight[c] || 0) + weight;
                const t = sp % 10;
                this.tailWeight[t] = (this.tailWeight[t] || 0) + weight;

                // 2. 状态转移统计 (邻期相关性)
                if (index < this.history.length - 1) {
                    const prevDraw = this.history[index + 1];
                    const prevSP = parseInt(prevDraw.specialNumber);
                    if (!isNaN(prevSP)) {
                        this.transitionMatrix[prevSP][sp] = (this.transitionMatrix[prevSP][sp] || 0) + 1;
                    }
                }
            }
        });
    }

    getOmissions() {
        const omissions: Record<number, number> = {};
        for (let n = 1; n <= 49; n++) {
            const index = this.history.findIndex(d => parseInt(d.specialNumber) === n);
            omissions[n] = index === -1 ? this.history.length : index;
        }
        return omissions;
    }
}

