  const msg = "🤖 <b>六合大数据助手</b>\n\n" +
              "请发送以下文本命令：\n\n" +
              "🔮 <b>一键预测</b> - 获取所有彩种预测\n" +
              "📊 <b>一键查看记录</b> - 获取所有彩种记录\n\n" +
              "⚙️ <b>管理员命令：</b>\n" +
              "🔄 <b>一键同步</b> - 同步最新数据\n" +
              "📢 <b>推送频道</b> - 推送预测到频道";

  // 尝试移除可能存在的旧键盘
  await sendMessage(token, chatId, msg, {
