import React from 'react';
import { Trophy, CheckCircle2, XCircle, TrendingUp } from 'lucide-react';
import { DrawResult, PredictionHistoryItem } from '../types.ts';
import { NUMBER_MAP } from '../constants.tsx';

interface PredictionHistoryListProps {
  predictions: PredictionHistoryItem[];
  drawHistory: DrawResult[];
}

export const PredictionHistoryList: React.FC<PredictionHistoryListProps> = ({ predictions, drawHistory }) => {
  if (!predictions || predictions.length === 0) return (
      <div className="text-center py-8 text-slate-400 text-xs">
          暂无预测记录
      </div>
  );

  const stats = (() => {
      const recent = predictions.slice(0, 20);
      let wins = 0;
      let checked = 0;
      recent.forEach(p => {
          const draw = drawHistory.find(d => d.drawNumber === p.drawNumber);
          if (draw) {
              checked++;
              const z = NUMBER_MAP[draw.specialNumber]?.zodiac;
              if (z && p.prediction.zodiacs.includes(z)) wins++;
          }
      });
      return { 
          rate: checked > 0 ? Math.round((wins / checked) * 100) : 0,
          total: checked,
          wins: wins
      };
  })();

  return (
    <div className="pb-8 space-y-4">
      <div className="bg-gradient-to-r from-slate-800 to-slate-900 rounded-2xl p-4 text-white shadow-xl border border-white/5 flex items-center justify-between">
          <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-full bg-amber-500/20 flex items-center justify-center border border-amber-500/30">
                  <TrendingUp className="text-amber-500 w-6 h-6" />
              </div>
              <div>
                  <h4 className="text-amber-400 font-bold text-sm">近期算法准率</h4>
                  <p className="text-[10px] text-slate-400">基于最近 {stats.total} 期开奖校验</p>
              </div>
          </div>
          <div className="text-right">
              <span className="text-3xl font-black text-white">{stats.rate}%</span>
              <p className="text-[10px] text-emerald-400 font-bold">已连准 {stats.wins} 期</p>
          </div>
      </div>

      <div className="space-y-3">
        {predictions.map((pred, i) => {
           const drawResult = drawHistory.find(d => d.drawNumber === pred.drawNumber);
           let status: 'pending' | 'win' | 'loss' = 'pending';
           let resultZodiac = '-';

           if (drawResult) {
               const spInfo = NUMBER_MAP[drawResult.specialNumber];
               resultZodiac = spInfo?.zodiac || '?';
               if (pred.prediction.zodiacs.includes(resultZodiac)) {
                   status = 'win';
               } else {
                   status = 'loss';
               }
           }

           return (
            <div key={i} className={`glass-card p-3 rounded-xl flex items-center justify-between relative overflow-hidden transition-all border ${status === 'win' ? 'border-emerald-500/30' : 'border-slate-200'}`}>
              <div className="flex flex-col gap-1 w-16 flex-shrink-0 border-r border-slate-200 pr-2">
                <span className={`font-mono text-xs font-bold ${status === 'win' ? 'text-emerald-600' : 'text-slate-700'}`}>
                    {pred.drawNumber}期
                </span>
                <span className="text-slate-400 text-[9px]">
                    {new Date(pred.timestamp).toLocaleDateString(undefined, {month:'numeric', day:'numeric'})}
                </span>
              </div>

              <div className="flex-1 px-4">
                  <div className="flex gap-1 flex-wrap mb-1">
                      {pred.prediction.zodiacs.slice(0, 6).map((z, idx) => (
                          <span key={idx} className={`text-[10px] w-6 h-6 flex items-center justify-center rounded-full shadow-sm transition-all ${z === resultZodiac ? 'bg-amber-500 text-white font-bold scale-110 shadow-amber-500/40 ring-2 ring-white' : 'bg-slate-100 text-slate-500 border border-slate-200'}`}>
                              {z}
                          </span>
                      ))}
                  </div>
                  <div className="text-[9px] text-slate-400 flex gap-2">
                      <span className="bg-slate-100 px-1 rounded">推荐{pred.prediction.colors.length}波</span>
                      <span className="bg-slate-100 px-1 rounded">精选18码</span>
                  </div>
              </div>

              <div className="flex flex-col items-center justify-center w-10 flex-shrink-0 pl-2 border-l border-slate-200">
                 {status === 'pending' ? (
                     <span className="text-[10px] text-slate-400 font-medium">待开</span>
                 ) : status === 'win' ? (
                     <>
                        <Trophy className="w-5 h-5 text-amber-500 mb-0.5 animate-bounce" />
                        <span className="text-[9px] text-emerald-600 font-black">收割</span>
                     </>
                 ) : (
                     <>
                        <XCircle className="w-5 h-5 text-slate-300 mb-0.5" />
                        <span className="text-[9px] text-slate-400">遗漏</span>
                     </>
                 )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { DrawResult, LotteryConfig, PredictionResult, PredictionHistoryItem } from './types.ts';
import { LOTTERY_CONFIGS } from './constants.tsx';
import { fetchLotteryHistory } from './geminiService.ts';
import { LotteryTabs } from './components/LotteryTabs.tsx';
import { LatestDraw } from './components/LatestDraw.tsx';
import { HistoryList } from './components/HistoryList.tsx';
import { PredictionHistoryList } from './components/PredictionHistoryList.tsx';
import { PredictionPanel } from './views/PredictionPanel.tsx';
import { History, Trophy } from 'lucide-react';

const App: React.FC = () => {
  const [selectedLottery, setSelectedLottery] = useState<LotteryConfig>(LOTTERY_CONFIGS[0]);
  const [history, setHistory] = useState<DrawResult[]>([]);
  const [prediction, setPrediction] = useState<PredictionResult | null>(null);
  const [predHistory, setPredHistory] = useState<PredictionHistoryItem[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeSection, setActiveSection] = useState<'none' | 'history' | 'prediction_history'>('none');

  useEffect(() => {
    // Fix: Access Telegram WebApp through any cast to avoid TypeScript property error on window object
    const tg = (window as any).Telegram;
    if (tg?.WebApp) {
      tg.WebApp.ready();
      tg.WebApp.expand();
    }
  }, []);

  const loadData = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const result = await fetchLotteryHistory(selectedLottery);
      setHistory(result.history || []);
      setPrediction(result.prediction);
      setPredHistory(result.predictionHistory || []);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "加载失败");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadData();
    setActiveSection('none');
  }, [selectedLottery]);

  const getNextDrawId = () => {
      if (history.length === 0) return '???';
      const last = history[0].drawNumber;
      try {
          return (BigInt(last) + 1n).toString();
      } catch {
          return `${last}_Next`;
      }
  };

  return (
    <div className="min-h-screen bg-slate-100 text-slate-800 font-sans selection:bg-amber-500/30 pb-10">
      <LotteryTabs 
        configs={LOTTERY_CONFIGS}
        selected={selectedLottery}
        onSelect={setSelectedLottery}
      />

      <LatestDraw draw={history[0] || null} isLoading={isLoading} />

      <div className="px-4 mt-6">
        <PredictionPanel 
          prediction={prediction}
          isLoading={isLoading}
          error={error}
          onPredict={loadData}
          lotteryName={selectedLottery.name}
          nextDrawId={getNextDrawId()}
        />
      </div>

      <div className="px-4 mt-8 flex gap-3">
          <button 
            onClick={() => setActiveSection(activeSection === 'history' ? 'none' : 'history')}
            className={`flex-1 py-3 rounded-xl flex items-center justify-center gap-2 text-xs font-bold transition-all shadow-sm border
                ${activeSection === 'history' ? 'bg-slate-800 text-white border-slate-800' : 'bg-white text-slate-500 border-slate-200 hover:bg-slate-50'}`}
          >
             <History className="w-4 h-4" /> 历史开奖
          </button>

          <button 
            onClick={() => setActiveSection(activeSection === 'prediction_history' ? 'none' : 'prediction_history')}
            className={`flex-1 py-3 rounded-xl flex items-center justify-center gap-2 text-xs font-bold transition-all shadow-sm border
                ${activeSection === 'prediction_history' ? 'bg-amber-500 text-white border-amber-500' : 'bg-white text-slate-500 border-slate-200 hover:bg-slate-50'}`}
          >
             <Trophy className="w-4 h-4" /> 预测战绩
          </button>
      </div>

      <div className="mx-4 mt-4 animate-in slide-in-from-top-2 duration-300">
          {activeSection === 'history' && history.length > 1 && (
             <HistoryList history={history} />
          )}

          {activeSection === 'prediction_history' && (
             <PredictionHistoryList predictions={predHistory} drawHistory={history} />
          )}
      </div>
    </div>
  );
};

export default App;

