import { NUMBER_MAP, NumberInfo } from '../constants.tsx';

// --- 基础数据与类型定义 ---
const ZODIACS = ['鼠', '牛', '虎', '兔', '龙', '蛇', '马', '羊', '猴', '鸡', '狗', '猪'];
const WUXING = ['金', '木', '水', '火', '土'];

// 动态权重接口
interface DynamicWeights {
    FREQUENCY: number;   // 热度权重
    OMISSION: number;    // 遗漏权重
    REPEAT: number;      // 重复/连号权重
    TAIL: number;        // 尾数趋势权重
    WUXING: number;      // 五行平衡权重
    ZODIAC_LINK: number; // 生肖关联权重
    description: string;
}

// 统计分析引擎
class AnalysisEngine {
    history: any[];
    freqMap: Record<number, number> = {};
    omissionMap: Record<number, number> = {};
    tailMap: Record<number, number> = {};
    wuxingTrend: Record<string, number> = {};

    // 缓存最近N期的生肖走势
    recentZodiacs: string[] = [];

    constructor(history: any[]) {
        this.history = history;
        this.analyzeBasicStats();
    }

    private analyzeBasicStats() {
        // 初始化
        for (let i = 1; i <= 49; i++) {
            this.freqMap[i] = 0;
            this.omissionMap[i] = 0;
        }
        for (let i = 0; i <= 9; i++) this.tailMap[i] = 0;
        WUXING.forEach(w => this.wuxingTrend[w] = 0);

        // 1. 计算遗漏值 (Omission)
        // 倒序遍历（从最新的往回找）
        for (let n = 1; n <= 49; n++) {
            const index = this.history.findIndex(d => parseInt(d.specialNumber) === n);
            this.omissionMap[n] = index === -1 ? this.history.length : index;
        }

        // 2. 计算加权频率与趋势 (从旧到新，近期权重高)
        const sampleSize = Math.min(this.history.length, 50);
        const subHistory = this.history.slice(0, sampleSize);

        subHistory.forEach((draw, idx) => {
            const num = parseInt(draw.specialNumber);
            if (isNaN(num)) return;

            // 时间衰减因子 (0.96)
            const weight = Math.pow(0.96, idx); 
            this.freqMap[num] += weight;

            // 尾数统计
            const tail = num % 10;
            this.tailMap[tail] += weight;

            // 五行统计
            const info = NUMBER_MAP[num];
            if (info) {
                this.wuxingTrend[info.wuxing] += weight;
            }

            // 记录最近生肖
            if (info && idx < 10) {
                this.recentZodiacs.push(info.zodiac);
            }
        });
    }

    // 获取某个号码的综合基础分
    getRawScore(num: number): { freq: number, omiss: number, tail: number, wuxing: number, zodiac: number } {
        const info = NUMBER_MAP[num];
        if (!info) return { freq:0, omiss:0, tail:0, wuxing:0, zodiac: 0 };

        const tail = num % 10;

        // 生肖关联分：如果该生肖在最近10期出现过，给予加分（热肖恒热）
        // 或者如果是上期的生肖的六合/三合生肖
        let zodiacScore = 0;
        if (this.recentZodiacs.includes(info.zodiac)) zodiacScore = 1;

        return {
            freq: this.freqMap[num] || 0,
            omiss: this.omissionMap[num] || 0,
            tail: this.tailMap[tail] || 0,
            wuxing: this.wuxingTrend[info.wuxing] || 0,
            zodiac: zodiacScore
        };
    }
}

// 自动调参器：计算过去30期各项指标与结果的相关性
function autoTuneWeights(history: any[]): DynamicWeights {
    // 默认权重
    const weights: DynamicWeights = {
        FREQUENCY: 1.0,
        OMISSION: 1.0,
        REPEAT: 1.0,
        TAIL: 1.0,
        WUXING: 1.0,
        ZODIAC_LINK: 1.0,
        description: "自适应均衡"
    };

    if (history.length < 20) return weights;

    // 回测样本量
    const testCount = Math.min(20, history.length - 1);
    const scores = { freq: 0, omiss: 0, tail: 0, wuxing: 0 };

    // 简单模拟回测：看哪种特征得分高的号码最终开出了
    for (let i = 0; i < testCount; i++) {
        const targetDraw = history[i];
        const targetNum = parseInt(targetDraw.specialNumber);
        if (isNaN(targetNum)) continue;

        // 使用当时的历史数据（不包含targetDraw及其之后的数据）
        // 这里的 i 是 index，history[i] 是当前，history.slice(i+1) 是过去
        const pastHistory = history.slice(i + 1);
        if (pastHistory.length < 10) break;

        const engine = new AnalysisEngine(pastHistory);
        const raw = engine.getRawScore(targetNum);

        // 累加特征命中分
        scores.freq += raw.freq;
        // 遗漏通常是反向指标（平均遗漏）或正向（极大遗漏回补），这里简化为正向关联检查
        // 如果开出的号码是遗漏值很大的，说明最近流行“冷号回补”
        scores.omiss += (raw.omiss > 20 ? 1 : 0); 
        scores.tail += raw.tail;
        scores.wuxing += raw.wuxing;
    }

    // 归一化并转化为权重
    // 如果 scores.freq 很高，说明近期热号频出，增加 FREQUENCY 权重
    const maxScore = Math.max(scores.freq, scores.omiss * 5, scores.tail, scores.wuxing); // 遗漏分值通常较小，加权平衡

    if (maxScore > 0) {
        weights.FREQUENCY = 1 + (scores.freq / maxScore);
        // 遗漏如果命中多，说明冷号多，增加遗漏权重
        weights.OMISSION = 1 + (scores.omiss * 5 / maxScore) * 1.5; 
        weights.TAIL = 1 + (scores.tail / maxScore);
        weights.WUXING = 1 + (scores.wuxing / maxScore);
    }

    // 生成策略描述
    const features = [];
    if (weights.FREQUENCY > 1.5) features.push("追热");
    if (weights.OMISSION > 1.5) features.push("博冷");
    if (weights.TAIL > 1.5) features.push("尾数");
    if (weights.WUXING > 1.5) features.push("五行");

    weights.description = features.length > 0 ? `自适应: ${features.join('+')}` : "自适应: 综合平衡";
    return weights;
}

export function generateDeterministicPrediction(history: any[]) {
    // 容错处理
    if (!history || history.length < 1) {
        return { zodiacs:[], numbers_18:[], numbers_8:[], heads:[], tails:[], colors:[], reasoning:"等待数据同步...", confidence:0 };
    }

    // 1. 自动计算最佳权重组合
    const weights = autoTuneWeights(history);
    const engine = new AnalysisEngine(history);

    // 2. 为每个号码打分
    const numberScores: { num: number, score: number }[] = [];

    for (let n = 1; n <= 49; n++) {
        const raw = engine.getRawScore(n);
        let score = 0;

        // 基础分
        score += raw.freq * 10 * weights.FREQUENCY;
        score += raw.tail * 5 * weights.TAIL;
        score += raw.wuxing * 5 * weights.WUXING;
        score += raw.zodiac * 8 * weights.ZODIAC_LINK;

        // 遗漏处理：
        // 如果遗漏值在 10-20 之间，容易回补，加分
        // 如果遗漏值 > 40，可能进入“死号”状态，稍微减分，除非 weights.OMISSION 很高（博冷模式）
        if (raw.omiss > 10 && raw.omiss < 25) {
            score += (raw.omiss * 0.5) * weights.OMISSION;
        } else if (raw.omiss >= 25) {
             // 遗漏极大时的策略
             if (weights.OMISSION > 1.5) {
                 score += (raw.omiss * 0.8) * weights.OMISSION; // 强力博冷
             } else {
                 score -= 5; // 常规防守，不碰极冷
             }
        }

        // 杀号逻辑：
        // 1. 绝杀连开3期以上的特码（概率极低）
        if (history.length >= 3) {
            const last1 = parseInt(history[0].specialNumber);
            const last2 = parseInt(history[1].specialNumber);
            const last3 = parseInt(history[2].specialNumber);
            if (n === last1 && n === last2 && n === last3) score -= 999;
        }

        // 2. 邻号规律（简单的马尔可夫链模拟）
        // 检查上期特码，给它的邻码（+1, -1）加分
        const lastSp = parseInt(history[0].specialNumber);
        if (!isNaN(lastSp)) {
            if (Math.abs(n - lastSp) === 1) score += 5 * weights.REPEAT;
        }

        numberScores.push({ num: n, score });
    }

    // 3. 排序与截取
    numberScores.sort((a, b) => b.score - a.score);

    // 生成各类推荐
    const numbers_18 = numberScores.slice(0, 18).map(i => i.num).sort((a,b)=>a-b);
    const numbers_8 = numberScores.slice(0, 8).map(i => i.num).sort((a,b)=>a-b);

    // 生肖统计
    const zodiacScoreMap: Record<string, number> = {};
    numberScores.forEach(item => {
        const z = NUMBER_MAP[item.num]?.zodiac;
        if (z) zodiacScoreMap[z] = (zodiacScoreMap[z] || 0) + item.score;
    });
    const zodiacs = Object.entries(zodiacScoreMap)
        .sort(([,a], [,b]) => b - a)
        .slice(0, 6)
        .map(([z]) => z);

    // 尾数统计
    const tailScoreMap: Record<number, number> = {};
    numberScores.slice(0, 20).forEach(item => { // 只看前20名的尾数分布
        const t = item.num % 10;
        tailScoreMap[t] = (tailScoreMap[t] || 0) + 1;
    });
    const tails = Object.entries(tailScoreMap)
        .sort(([,a], [,b]) => b - a)
        .slice(0, 4)
        .map(([t]) => parseInt(t))
        .sort((a,b)=>a-b);

    // 头数统计
    const headScoreMap: Record<number, number> = {};
    numberScores.slice(0, 15).forEach(item => {
        const h = Math.floor(item.num / 10);
        headScoreMap[h] = (headScoreMap[h] || 0) + 1;
    });
    const heads = Object.entries(headScoreMap)
        .sort(([,a], [,b]) => b - a)
        .slice(0, 2) // 只取前2个最热头
        .map(([h]) => parseInt(h))
        .sort((a,b)=>a-b);

    // 波色分析
    const colorScores = { red: 0, blue: 0, green: 0 };
    numberScores.slice(0, 12).forEach(item => {
        const c = NUMBER_MAP[item.num]?.color;
        if (c && colorScores[c] !== undefined) colorScores[c]++;
    });
    const colors = Object.entries(colorScores)
        .sort(([,a], [,b]) => b - a)
        .map(([c]) => c)
        .slice(0, 2); // 推荐两波

    // 信心值计算 (基于第一名和第十名的分数差，差越大说明头部越明显)
    const topScore = numberScores[0].score;
    const midScore = numberScores[10].score;
    const gap = topScore - midScore;
    // 基础分 60，根据差距浮动
    const confidence = Math.min(95, Math.floor(60 + (gap * 2) + (history.length > 50 ? 10 : 0)));

    return {
        zodiacs,
        numbers_18,
        numbers_8,
        heads,
        tails,
        colors,
        reasoning: `【${weights.description}】基于近${Math.min(30, history.length)}期数据回测建模`,
        confidence
    };
}

