import { NUMBER_MAP, ZODIAC_RELATIONS, NumberInfo } from '../constants.tsx';

// --- 全局常量 ---
const ZODIACS = ['鼠', '牛', '虎', '兔', '龙', '蛇', '马', '羊', '猴', '鸡', '狗', '猪'];

// --- 核心分析引擎 ---
class FullHistoryEngine {
    history: any[];

    // 1. 基础统计
    globalFreq: Record<number, number> = {};
    currentOmission: Record<number, number> = {};

    // 2. 趋势转移矩阵 (Transition Matrices)
    // 记录: [上期特征] -> { [本期特征]: 权重次数 }
    numTransition: Record<number, Record<number, number>> = {};   // 号码->号码
    zodiacTransition: Record<string, Record<string, number>> = {}; // 生肖->生肖
    tailTransition: Record<number, Record<number, number>> = {};   // 尾数->尾数
    headTransition: Record<number, Record<number, number>> = {};   // 头数->头数

    // 3. 平特关联统计 (Flat-to-Special Statistics)
    // 统计上期平码的某个特征（如尾数），在本期特码中出现的概率
    // 逻辑：如果上期平码有尾数 1,3,5,6,8,9，本期特码尾数是 3，则命中。
    flatTailStats = {
        hitCount: 0,
        totalCount: 0,
        probability: 0
    };

    // 4. 动态权重因子 (基于该彩种历史准确度自动调整)
    strategyWeights = {
        markovZodiac: 1.0, // 生肖走势权重
        markovTail: 1.0,   // 尾数走势权重
        markovHead: 1.0,   // 头数走势权重
        flatStrategy: 1.0, // 平码关联权重
        balance: 1.0       // 均值回归权重
    };

    balanceStats = {
        oddCount: 0,
        totalCount: 0,
        colorCounts: { red: 0, blue: 0, green: 0 } as Record<string, number>
    };

    constructor(history: any[]) {
        this.history = history;
        this.initStats();
        this.processFullHistory();
        this.adjustDynamicWeights();
    }

    private initStats() {
        for (let i = 1; i <= 49; i++) this.globalFreq[i] = 0;
        for (let i = 1; i <= 49; i++) {
            const lastIdx = this.history.findIndex(d => parseInt(d.specialNumber) === i);
            this.currentOmission[i] = lastIdx === -1 ? this.history.length : lastIdx;
        }
    }

    private processFullHistory() {
        const total = this.history.length;

        // 倒序遍历：从旧到新构建矩阵
        for (let i = total - 1; i >= 0; i--) {
            const currentDraw = this.history[i];
            const currentNum = parseInt(currentDraw.specialNumber);

            if (isNaN(currentNum)) continue;

            // --- 基础热度 ---
            // 线性加权：近期数据权重更高
            const timeWeight = 1 + ((total - 1 - i) / total) * 2; 
            this.globalFreq[currentNum] += timeWeight;

            const curInfo = NUMBER_MAP[currentNum];
            if (!curInfo) continue;

            // --- 偏差统计 ---
            this.balanceStats.totalCount++;
            if (!curInfo.isEven) this.balanceStats.oddCount++;
            this.balanceStats.colorCounts[curInfo.color]++;

            // --- 关联分析 (需要有"上一期") ---
            // i 是当前索引，i+1 是时间上的上一期
            if (i < total - 1) {
                const prevDraw = this.history[i + 1];
                const prevNum = parseInt(prevDraw.specialNumber);

                if (!isNaN(prevNum)) {
                    const prevInfo = NUMBER_MAP[prevNum];

                    // A. 构建特码转移矩阵
                    this.recordTransition(this.numTransition, prevNum, currentNum);

                    if (prevInfo) {
                        this.recordTransition(this.zodiacTransition, prevInfo.zodiac, curInfo.zodiac);
                    }

                    const prevTail = prevNum % 10;
                    const curTail = currentNum % 10;
                    this.recordTransition(this.tailTransition, prevTail, curTail);

                    const prevHead = Math.floor(prevNum / 10);
                    const curHead = Math.floor(currentNum / 10);
                    this.recordTransition(this.headTransition, prevHead, curHead);

                    // B. 平码-特码 关联分析
                    // 检查本期特码的尾数，是否出现在了上期平码的尾数列表中
                    if (Array.isArray(prevDraw.numbers)) {
                        const prevFlatTails = prevDraw.numbers.map((n: number) => n % 10);
                        this.flatTailStats.totalCount++;
                        if (prevFlatTails.includes(curTail)) {
                            this.flatTailStats.hitCount++;
                        }
                    }
                }
            }
        }

        // 计算平特策略的历史概率
        if (this.flatTailStats.totalCount > 0) {
            this.flatTailStats.probability = this.flatTailStats.hitCount / this.flatTailStats.totalCount;
        }
    }

    // 辅助函数：记录转移
    private recordTransition(matrix: any, from: any, to: any) {
        if (!matrix[from]) matrix[from] = {};
        // 增加计数，越近期的数据对矩阵贡献略大一点点，但不像频率那么夸张
        matrix[from][to] = (matrix[from][to] || 0) + 1;
    }

    // 根据历史拟合度，自动调整算法权重
    private adjustDynamicWeights() {
        // 如果平特尾数关联率极高 (>65%)，大幅增加该策略权重
        if (this.flatTailStats.probability > 0.65) {
            this.strategyWeights.flatStrategy = 3.5;
            this.strategyWeights.markovTail = 0.5; // 此消彼长
        } else if (this.flatTailStats.probability < 0.3) {
            this.strategyWeights.flatStrategy = 0.2; // 关联度低，忽略此策略
        }

        // 简单的熵检测：如果某个生肖转移特别集中（Max count 很大），说明生肖规律强
        // 这里简化处理：默认生肖和尾数权重较高，因为这是六合彩的核心
        this.strategyWeights.markovZodiac = 2.0;
        this.strategyWeights.markovTail = 1.8;
        this.strategyWeights.markovHead = 1.5;
    }

    // --- 评分获取器 ---

    getMarkovScore(lastNum: number, candidate: number): number {
        const cInfo = NUMBER_MAP[candidate];
        if (!cInfo) return 0;
        const lastInfo = NUMBER_MAP[lastNum];
        if (!lastInfo) return 0;

        let score = 0;

        // 1. 生肖转移概率
        const zCount = this.zodiacTransition[lastInfo.zodiac]?.[cInfo.zodiac] || 0;
        score += zCount * this.strategyWeights.markovZodiac;

        // 2. 尾数转移概率
        const lastTail = lastNum % 10;
        const candTail = candidate % 10;
        const tCount = this.tailTransition[lastTail]?.[candTail] || 0;
        score += tCount * this.strategyWeights.markovTail;

        // 3. 头数转移概率
        const lastHead = Math.floor(lastNum / 10);
        const candHead = Math.floor(candidate / 10);
        const hCount = this.headTransition[lastHead]?.[candHead] || 0;
        score += hCount * this.strategyWeights.markovHead;

        return score;
    }

    getFlatStrategyScore(prevFlatNumbers: number[], candidate: number): number {
        // 如果历史数据显示平码尾数经常掉落到特码尾数
        if (this.flatTailStats.probability < 0.45) return 0; // 概率低则不参考

        const candTail = candidate % 10;
        const prevFlatTails = prevFlatNumbers.map(n => n % 10);

        if (prevFlatTails.includes(candTail)) {
            // 命中策略，加分。分值取决于历史概率
            return 10 * this.flatTailStats.probability * this.strategyWeights.flatStrategy;
        }
        return 0;
    }
}

export function generateDeterministicPrediction(history: any[]) {
    if (!history || history.length < 5) {
        return { zodiacs:[], numbers_18:[], numbers_8:[], heads:[], tails:[], colors:[], reasoning:"数据不足", confidence:0 };
    }

    const engine = new FullHistoryEngine(history);
    const lastDraw = history[0]; // 最新一期
    const lastNum = parseInt(lastDraw.specialNumber);
    const hasLast = !isNaN(lastNum);

    const scores: { n: number, s: number }[] = [];

    // --- 综合评分 ---
    for (let n = 1; n <= 49; n++) {
        let finalScore = 0;

        // 1. 基础热度 (权重中)
        const freqScore = (engine.globalFreq[n] / history.length) * 15; 
        finalScore += freqScore;

        if (hasLast) {
            // 2. 深度转移规律 (生肖/头/尾) - 核心算法
            const mkScore = engine.getMarkovScore(lastNum, n);
            finalScore += mkScore;

            // 3. 平特策略 (Flat-to-Special) - 增强型算法
            if (Array.isArray(lastDraw.numbers)) {
                const flatScore = engine.getFlatStrategyScore(lastDraw.numbers, n);
                finalScore += flatScore;
            }

            // 4. 生肖三合六合 (玄学修正)
            const lastInfo = NUMBER_MAP[lastNum];
            const curInfo = NUMBER_MAP[n];
            if (lastInfo && curInfo) {
                const rel = ZODIAC_RELATIONS[lastInfo.zodiac];
                if (rel.friends.includes(curInfo.zodiac)) finalScore += 5; // 加分
                if (rel.clash === curInfo.zodiac) finalScore -= 3; // 冲肖稍微减分(但不绝对，有时候冲肖也出)
            }
        }

        // 5. 遗漏值处理 (杀极冷)
        const omiss = engine.currentOmission[n];
        if (omiss > 40) finalScore -= 20; // 极度深冷，杀
        if (omiss >= 10 && omiss <= 25) finalScore += 4; // 黄金回补期

        // 6. 杀重号 (特码连开概率极低)
        if (hasLast && n === lastNum) finalScore -= 50;

        scores.push({ n, s: finalScore });
    }

    // --- 排序 ---
    scores.sort((a, b) => {
        if (Math.abs(b.s - a.s) > 0.001) return b.s - a.s;
        return b.n - a.n; // 分数相同选大号
    });

    // --- 提取结果 ---
    const top18 = scores.slice(0, 18).map(x => x.n).sort((a,b)=>a-b);

    // 精选8码：从前18名里，再挑分最高的8个
    const top8 = scores.slice(0, 8).map(x => x.n).sort((a,b)=>a-b);

    // 智能提取六肖
    // 逻辑：统计前20名号码中，各生肖累积的分数，取前6名
    const zodiacScores: Record<string, number> = {};
    scores.slice(0, 25).forEach(({n, s}) => {
        const z = NUMBER_MAP[n]?.zodiac;
        if (z) zodiacScores[z] = (zodiacScores[z] || 0) + s + (100 / (scores.indexOf({n,s}) + 1)); // 排名加权
    });
    const topZodiacs = Object.entries(zodiacScores)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 6)
        .map(x => x[0]);

    // 智能提取尾数
    const tailScores: Record<number, number> = {};
    scores.slice(0, 20).forEach(({n, s}) => {
        const t = n % 10;
        tailScores[t] = (tailScores[t] || 0) + s;
    });
    const topTails = Object.entries(tailScores)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 4)
        .map(x => parseInt(x[0]))
        .sort((a,b)=>a-b);

    // 智能提取头数
    const headScores: Record<number, number> = {};
    scores.slice(0, 15).forEach(({n, s}) => {
        const h = Math.floor(n / 10);
        headScores[h] = (headScores[h] || 0) + s;
    });
    const topHeads = Object.entries(headScores)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 2)
        .map(x => parseInt(x[0]))
        .sort((a,b)=>a-b);

    // 智能提取波色
    const colorScores: Record<string, number> = { red:0, blue:0, green:0 };
    scores.slice(0, 15).forEach(({n, s}) => {
        const c = NUMBER_MAP[n]?.color;
        if (c) colorScores[c] += s;
    });
    const topColors = Object.entries(colorScores)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 2)
        .map(x => x[0]);

    // 生成文案
    const tailRatePct = Math.round(engine.flatTailStats.probability * 100);
    let reasoning = "";
    if (tailRatePct > 55) {
        reasoning = `【平特强关联】历史数据显示上期平码尾数极高概率(${tailRatePct}%)掉落特码。`;
    } else {
        const bestFeature = topZodiacs[0];
        reasoning = `【大数据轨迹】生肖/头尾数转移矩阵锁定，重点关注${bestFeature}。`;
    }

    const confidence = Math.min(95, 65 + Math.floor(history.length / 10) + (tailRatePct > 60 ? 10 : 0));

    return {
        zodiacs: topZodiacs,
        numbers_18: top18,
        numbers_8: top8,
        heads: topHeads,
        tails: topTails,
        colors: topColors,
        reasoning,
        confidence
    };
}

import { generateDeterministicPrediction } from '../analysis';

export async function onRequestPost(context: any) {
  const { request, env } = context;

  try {
    const { lotteryId } = await request.json();

    // --- 获取更多历史数据以支持算法回测 ---
    // 增加 LIMIT 以确保实时计算时的准确性 (400期能覆盖约2-3年的数据，足够建立统计模型)
    let historyData: any[] = [];
    if (env.DB) {
        const { results } = await env.DB.prepare(`
            SELECT * FROM lottery_draws 
            WHERE lottery_id = ? 
            ORDER BY draw_number DESC 
            LIMIT 400
        `).bind(lotteryId).all();

        historyData = results.map((row: any) => ({
            drawNumber: row.draw_number,
            date: row.open_time,
            numbers: JSON.parse(row.numbers),
            specialNumber: row.special_number
        }));
    }

    // --- 获取最新预测 ---
    let prediction: any = null;
    if (env.DB) {
        const predRow = await env.DB.prepare(`
            SELECT data, updated_at FROM admin_predictions WHERE lottery_id = ?
        `).bind(lotteryId).first();

        if (predRow && predRow.data) {
            prediction = JSON.parse(predRow.data as string);
            prediction.timestamp = predRow.updated_at;
        }
    }

    // --- 兜底逻辑：如果数据库没有预测，实时生成 ---
    if (!prediction && historyData.length > 0) {
        const generated = generateDeterministicPrediction(historyData);
        prediction = {
            ...generated,
            timestamp: Date.now()
        };
        // 注意：这里不写入数据库，保持 GET/Query 操作的无副作用性，
        // 且避免并发写入冲突，写入操作保留给 webhook 或同步动作。
    }

    // --- 获取预测历史记录 ---
    let predictionHistory: any[] = [];
    if (env.DB) {
        const { results } = await env.DB.prepare(`
            SELECT draw_number, data, created_at 
            FROM prediction_history 
            WHERE lottery_id = ? 
            ORDER BY draw_number DESC 
            LIMIT 30
        `).bind(lotteryId).all();

        predictionHistory = results.map((row: any) => ({
            drawNumber: row.draw_number,
            prediction: JSON.parse(row.data as string),
            timestamp: row.created_at
        }));
    }

    return new Response(JSON.stringify({ 
        history: historyData,
        prediction: prediction,
        predictionHistory: predictionHistory
    }), {
      headers: { "Content-Type": "application/json" }
    });

  } catch (error: any) {
    return new Response(JSON.stringify({ error: error.message }), {
      status: 500,
      headers: { "Content-Type": "application/json" }
    });
  }
}

import { NUMBER_MAP, ZODIAC_RELATIONS, NumberInfo } from '../constants.tsx';

// --- 全局常量 ---
const ZODIACS = ['鼠', '牛', '虎', '兔', '龙', '蛇', '马', '羊', '猴', '鸡', '狗', '猪'];

// --- 核心分析引擎 ---
class FullHistoryEngine {
    history: any[];

    // 1. 基础统计
    globalFreq: Record<number, number> = {};

    // 2. 趋势转移矩阵 (Transition Matrices)
    numTransition: Record<number, Record<number, number>> = {};   // 号码->号码
    zodiacTransition: Record<string, Record<string, number>> = {}; // 生肖->生肖
    tailTransition: Record<number, Record<number, number>> = {};   // 尾数->尾数
    wuxingTransition: Record<string, Record<string, number>> = {}; // 五行->五行 (新增)

    // 3. 杀肖/排除逻辑统计 (Exclusion Stats)
    // 记录某个生肖在最近 N 期出现的次数，用于判断是否过热
    recentZodiacCounts: Record<string, number> = {}; 

    // 4. 平特关联
    flatTailStats = { hitCount: 0, totalCount: 0, probability: 0 };

    // 5. 权重因子
    weights = {
        freq: 10,       // 基础热度
        transZodiac: 5.0, // 生肖转移
        transTail: 4.0,   // 尾数转移
        transWuxing: 3.5, // 五行转移 (新增)
        flatStrategy: 0,  // 平特 (动态调整)
        killPenalty: -50, // 绝杀惩罚 (新增)
        hotPenalty: -20   // 过热惩罚 (新增)
    };

    constructor(history: any[]) {
        this.history = history;
        this.initStats();
        this.processFullHistory();
        this.adjustDynamicWeights();
    }

    private initStats() {
        for (let i = 1; i <= 49; i++) this.globalFreq[i] = 0;
        ZODIACS.forEach(z => this.recentZodiacCounts[z] = 0);
    }

    private processFullHistory() {
        const total = this.history.length;

        // 统计最近 10 期的生肖热度 (用于判断过热)
        for (let i = 0; i < Math.min(10, total); i++) {
            const num = parseInt(this.history[i].specialNumber);
            if (!isNaN(num)) {
                const info = NUMBER_MAP[num];
                if (info) this.recentZodiacCounts[info.zodiac]++;
            }
        }

        // 倒序遍历构建矩阵
        for (let i = total - 1; i >= 0; i--) {
            const currentDraw = this.history[i];
            const currentNum = parseInt(currentDraw.specialNumber);
            if (isNaN(currentNum)) continue;

            const curInfo = NUMBER_MAP[currentNum];
            if (!curInfo) continue;

            // 基础频率 (近期权重更高)
            const recency = 1 + ((total - 1 - i) / total) * 3;
            this.globalFreq[currentNum] += recency;

            // 关联分析 (Current <- Previous)
            if (i < total - 1) {
                const prevDraw = this.history[i + 1];
                const prevNum = parseInt(prevDraw.specialNumber);

                if (!isNaN(prevNum)) {
                    const prevInfo = NUMBER_MAP[prevNum];

                    // 1. 生肖转移
                    if (prevInfo) this.recordTransition(this.zodiacTransition, prevInfo.zodiac, curInfo.zodiac);

                    // 2. 尾数转移
                    this.recordTransition(this.tailTransition, prevNum % 10, currentNum % 10);

                    // 3. 五行转移
                    if (prevInfo) this.recordTransition(this.wuxingTransition, prevInfo.wuxing, curInfo.wuxing);

                    // 4. 平特关联
                    if (Array.isArray(prevDraw.numbers)) {
                        const prevFlatTails = prevDraw.numbers.map((n: number) => n % 10);
                        this.flatTailStats.totalCount++;
                        if (prevFlatTails.includes(currentNum % 10)) {
                            this.flatTailStats.hitCount++;
                        }
                    }
                }
            }
        }

        if (this.flatTailStats.totalCount > 0) {
            this.flatTailStats.probability = this.flatTailStats.hitCount / this.flatTailStats.totalCount;
        }
    }

    private recordTransition(matrix: any, from: any, to: any) {
        if (!matrix[from]) matrix[from] = {};
        matrix[from][to] = (matrix[from][to] || 0) + 1;
    }

    private adjustDynamicWeights() {
        // 如果平特策略极准，大幅加权
        if (this.flatTailStats.probability > 0.6) {
            this.weights.flatStrategy = 40; 
        } else {
            this.weights.flatStrategy = 5;
        }
    }

    // --- 核心评分逻辑 ---

    getCompositeScore(lastNum: number, candidate: number, prevFlatNums: number[]): number {
        const cInfo = NUMBER_MAP[candidate];
        const lastInfo = NUMBER_MAP[lastNum];
        if (!cInfo || !lastInfo) return 0;

        let score = 0;

        // 1. 生肖转移概率 (Zodiac Markov)
        const zTransCount = this.zodiacTransition[lastInfo.zodiac]?.[cInfo.zodiac] || 0;
        const zTotal = this.sumValues(this.zodiacTransition[lastInfo.zodiac]);
        const zProb = zTotal > 0 ? zTransCount / zTotal : 0;

        // 【绝杀逻辑】：如果历史上“牛”之后开“龙”的概率低于 2%，视为绝杀
        if (zTotal > 20 && zProb < 0.02) {
             score += this.weights.killPenalty; 
        } else {
             score += zProb * 100 * this.weights.transZodiac;
        }

        // 【过热惩罚】：如果该生肖最近10期出了3次以上，进行概率回落惩罚
        if (this.recentZodiacCounts[cInfo.zodiac] >= 3) {
            score += this.weights.hotPenalty;
        }

        // 2. 五行转移概率 (Wu-Xing Flow)
        const wTransCount = this.wuxingTransition[lastInfo.wuxing]?.[cInfo.wuxing] || 0;
        score += wTransCount * this.weights.transWuxing;

        // 3. 尾数转移概率 (Tail Markov)
        const lastTail = lastNum % 10;
        const cTail = candidate % 10;
        const tTransCount = this.tailTransition[lastTail]?.[cTail] || 0;
        score += tTransCount * this.weights.transTail;

        // 4. 平特尾数关联 (Flat-Code Correlation)
        if (prevFlatNums) {
            const prevTails = prevFlatNums.map(n => n % 10);
            if (prevTails.includes(cTail)) {
                // 如果历史数据显示平特关联度高，则加分；否则加分很少
                score += this.flatTailStats.probability * this.weights.flatStrategy;
            }
        }

        // 5. 基础频率修正
        score += (this.globalFreq[candidate] / this.history.length) * this.weights.freq;

        return score;
    }

    private sumValues(obj: Record<any, number> | undefined): number {
        if (!obj) return 0;
        return Object.values(obj).reduce((a, b) => a + b, 0);
    }
}

export function generateDeterministicPrediction(history: any[]) {
    // 数据量过少时返回空
    if (!history || history.length < 10) {
        return { zodiacs:[], numbers_18:[], numbers_8:[], heads:[], tails:[], colors:[], reasoning:"数据积累中", confidence:0 };
    }

    const engine = new FullHistoryEngine(history);
    const lastDraw = history[0];
    const lastNum = parseInt(lastDraw.specialNumber);

    // 计算所有号码得分
    const scores: { n: number, s: number, z: string, t: number }[] = [];

    for (let n = 1; n <= 49; n++) {
        const s = engine.getCompositeScore(lastNum, n, lastDraw.numbers);
        scores.push({ n, s, z: NUMBER_MAP[n].zodiac, t: n % 10 });
    }

    // 排序
    scores.sort((a, b) => b.s - a.s);

    // --- 智能提取策略 (V2.0) ---

    // 1. 提取六肖：聚合号码分数 + 覆盖率修正
    // 我们不只是简单相加，还要看该生肖下的号码是否普遍高分
    const zodiacScores: Record<string, number> = {};
    scores.forEach(({ s, z }) => {
        // 只统计正分数的号码，负分(被杀)的号码会拉低生肖总分
        zodiacScores[z] = (zodiacScores[z] || 0) + s; 
    });

    const topZodiacs = Object.entries(zodiacScores)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 6)
        .map(x => x[0]);

    // 2. 提取18码：优先从推荐的六肖中，选出分数最高的号码
    // 这样保证了“生肖推荐”和“号码推荐”的一致性
    const numbersInZodiacs = scores.filter(x => topZodiacs.includes(x.z));
    const numbersOutside = scores.filter(x => !topZodiacs.includes(x.z));

    // 策略：18码中，14个来自推荐生肖，4个来自防守生肖(外围最高分)
    const top18 = [
        ...numbersInZodiacs.slice(0, 14),
        ...numbersOutside.slice(0, 4)
    ].map(x => x.n).sort((a,b) => a-b); // 最后按数字大小排序

    // 3. 提取8码 (从18码中再精选)
    // 选取绝对分数最高的8个
    const top8 = scores.slice(0, 8).map(x => x.n).sort((a,b) => a-b);

    // 4. 提取头尾波色
    const tailScores: Record<number, number> = {};
    const headScores: Record<number, number> = {};
    const colorScores: Record<string, number> = { red:0, blue:0, green:0 };

    scores.slice(0, 20).forEach(({n, s}) => { // 只用前20名的高分号来定特征
        tailScores[n % 10] = (tailScores[n % 10] || 0) + s;
        headScores[Math.floor(n / 10)] = (headScores[Math.floor(n / 10)] || 0) + s;
        const c = NUMBER_MAP[n]?.color;
        if(c) colorScores[c] += s;
    });

    const topTails = Object.entries(tailScores).sort((a,b)=>b[1]-a[1]).slice(0,4).map(x=>parseInt(x[0])).sort((a,b)=>a-b);
    const topHeads = Object.entries(headScores).sort((a,b)=>b[1]-a[1]).slice(0,2).map(x=>parseInt(x[0])).sort((a,b)=>a-b);
    const topColors = Object.entries(colorScores).sort((a,b)=>b[1]-a[1]).slice(0,2).map(x=>x[0]);

    // 生成文案
    const lastInfo = NUMBER_MAP[lastNum];
    let reasoning = "大数据综合运算完成。";

    if (engine.flatTailStats.probability > 0.6) {
        reasoning = `【平特策略】上期平码尾数高频下移，重点锁定相关尾数。`;
    } else if (lastInfo) {
        // 查找最强的五行关联
        const bestWuxing = Object.entries(engine.wuxingTransition[lastInfo.wuxing] || {})
            .sort((a,b) => b[1] - a[1])[0];
        if (bestWuxing) {
            reasoning = `【五行流转】${lastInfo.wuxing}行 转 ${bestWuxing[0]}行 概率极高，已加权。`;
        }
    }

    const confidence = Math.min(98, 70 + Math.floor(history.length / 20));

    return {
        zodiacs: topZodiacs,
        numbers_18: top18,
        numbers_8: top8,
        heads: topHeads,
        tails: topTails,
        colors: topColors,
        reasoning,
        confidence
    };
}

import { NUMBER_MAP, ZODIAC_RELATIONS, NumberInfo } from '../constants.tsx';

// --- 全局常量 ---
const ZODIACS = ['鼠', '牛', '虎', '兔', '龙', '蛇', '马', '羊', '猴', '鸡', '狗', '猪'];

// --- 辅助函数：计算合数 (个位+十位) ---
const getDigitSum = (num: number): number => {
    const tens = Math.floor(num / 10);
    const units = num % 10;
    return (tens + units) % 10; // 取合数的尾数，如 39->12->2
};

// --- 辅助函数：计算012路 (除3余数) ---
const getMod3 = (num: number): number => num % 3;

// --- 核心分析引擎 ---
class FullHistoryEngine {
    history: any[];

    // 1. 基础统计
    globalFreq: Record<number, number> = {};

    // 2. 数理趋势矩阵 (Transition Matrices)
    // 记录: [上期特征] -> { [本期特征]: 权重次数 }
    zodiacTransition: Record<string, Record<string, number>> = {}; // 生肖->生肖
    tailTransition: Record<number, Record<number, number>> = {};   // 尾数->尾数
    mod3Transition: Record<number, Record<number, number>> = {};   // 012路->012路 (新)
    sumTransition: Record<number, Record<number, number>> = {};    // 合数->合数 (新)

    // 3. 杀号逻辑统计
    // 记录某个生肖在最近 15 期出现的次数，用于判断是否"超标"
    recentZodiacCounts: Record<string, number> = {}; 

    // 4. 平特关联 (Ping-Te Strategy)
    flatTailStats = { hitCount: 0, totalCount: 0, probability: 0 };

    // 5. 权重因子 (纯数理版)
    weights = {
        freq: 8,          // 基础热度
        transZodiac: 6.0, // 生肖惯性
        transTail: 5.0,   // 尾数路径
        transMod3: 4.0,   // 012路数学规律
        transSum: 3.5,    // 合数规律
        flatStrategy: 0,  // 平特 (动态)
        killPenalty: -100,// 绝杀惩罚 (大幅度扣分，直接排除)
        overheatPenalty: -30 // 过热惩罚
    };

    constructor(history: any[]) {
        this.history = history;
        this.initStats();
        this.processFullHistory();
        this.adjustDynamicWeights();
    }

    private initStats() {
        for (let i = 1; i <= 49; i++) this.globalFreq[i] = 0;
        ZODIACS.forEach(z => this.recentZodiacCounts[z] = 0);
    }

    private processFullHistory() {
        const total = this.history.length;

        // 统计最近 15 期的生肖热度
        for (let i = 0; i < Math.min(15, total); i++) {
            const num = parseInt(this.history[i].specialNumber);
            if (!isNaN(num)) {
                const info = NUMBER_MAP[num];
                if (info) this.recentZodiacCounts[info.zodiac]++;
            }
        }

        // 倒序遍历构建矩阵
        for (let i = total - 1; i >= 0; i--) {
            const currentDraw = this.history[i];
            const currentNum = parseInt(currentDraw.specialNumber);
            if (isNaN(currentNum)) continue;

            const curInfo = NUMBER_MAP[currentNum];
            if (!curInfo) continue;

            // 基础频率 (越近越重要)
            const recency = 1 + ((total - 1 - i) / total) * 2;
            this.globalFreq[currentNum] += recency;

            // 关联分析 (Current <- Previous)
            if (i < total - 1) {
                const prevDraw = this.history[i + 1];
                const prevNum = parseInt(prevDraw.specialNumber);

                if (!isNaN(prevNum)) {
                    const prevInfo = NUMBER_MAP[prevNum];

                    // 1. 生肖转移
                    if (prevInfo) this.recordTransition(this.zodiacTransition, prevInfo.zodiac, curInfo.zodiac);

                    // 2. 尾数转移
                    this.recordTransition(this.tailTransition, prevNum % 10, currentNum % 10);

                    // 3. 012路转移 (数学规律)
                    this.recordTransition(this.mod3Transition, getMod3(prevNum), getMod3(currentNum));

                    // 4. 合数转移 (数学规律)
                    this.recordTransition(this.sumTransition, getDigitSum(prevNum), getDigitSum(currentNum));

                    // 5. 平特关联 (上期平码 -> 本期特码)
                    if (Array.isArray(prevDraw.numbers)) {
                        const prevFlatTails = prevDraw.numbers.map((n: number) => n % 10);
                        this.flatTailStats.totalCount++;
                        if (prevFlatTails.includes(currentNum % 10)) {
                            this.flatTailStats.hitCount++;
                        }
                    }
                }
            }
        }

        if (this.flatTailStats.totalCount > 0) {
            this.flatTailStats.probability = this.flatTailStats.hitCount / this.flatTailStats.totalCount;
        }
    }

    private recordTransition(matrix: any, from: any, to: any) {
        if (!matrix[from]) matrix[from] = {};
        matrix[from][to] = (matrix[from][to] || 0) + 1;
    }

    private adjustDynamicWeights() {
        // 动态调整策略权重
        if (this.flatTailStats.probability > 0.65) {
            this.weights.flatStrategy = 45; // 极高关联，重注平特
        } else if (this.flatTailStats.probability > 0.5) {
            this.weights.flatStrategy = 15;
        } else {
            this.weights.flatStrategy = 2;
        }
    }

    // --- 核心评分逻辑 ---
    getCompositeScore(lastNum: number, candidate: number, prevFlatNums: number[]): number {
        const cInfo = NUMBER_MAP[candidate];
        const lastInfo = NUMBER_MAP[lastNum];
        if (!cInfo || !lastInfo) return 0;

        let score = 0;

        // --- 1. 生肖转移与绝杀 (Zodiac Logic) ---
        const zTransCount = this.zodiacTransition[lastInfo.zodiac]?.[cInfo.zodiac] || 0;
        const zTotal = this.sumValues(this.zodiacTransition[lastInfo.zodiac]);
        const zProb = zTotal > 0 ? zTransCount / zTotal : 0;

        // 【绝杀】: 如果历史数据充足(>30期)，且该生肖转移从未发生过(0次)或概率极低(<2%)
        // 我们直接扣除巨大分数，将其从预测列表中踢出
        if (zTotal > 30 && zProb < 0.015) {
             score += this.weights.killPenalty; 
        } else {
             score += zProb * 100 * this.weights.transZodiac;
        }

        // 【杀热号】: 生肖最近15期出现4次以上，视为极限，大概率休息
        if (this.recentZodiacCounts[cInfo.zodiac] >= 4) {
            score += this.weights.overheatPenalty;
        }

        // --- 2. 012路数学规律 (Modulo-3) ---
        const lastMod = getMod3(lastNum);
        const candMod = getMod3(candidate);
        const modCount = this.mod3Transition[lastMod]?.[candMod] || 0;
        const modTotal = this.sumValues(this.mod3Transition[lastMod]);
        const modProb = modTotal > 0 ? modCount / modTotal : 0;
        score += modProb * 50 * this.weights.transMod3;

        // --- 3. 合数规律 (Digit Sum) ---
        const lastSum = getDigitSum(lastNum);
        const candSum = getDigitSum(candidate);
        const sumCount = this.sumTransition[lastSum]?.[candSum] || 0;
        // 合数比较散，权重稍微低一点，主要用于辅助定胆
        score += sumCount * this.weights.transSum;

        // --- 4. 尾数路径 (Tail Logic) ---
        const lastTail = lastNum % 10;
        const cTail = candidate % 10;
        const tCount = this.tailTransition[lastTail]?.[cTail] || 0;
        const tTotal = this.sumValues(this.tailTransition[lastTail]);
        const tProb = tTotal > 0 ? tCount / tTotal : 0;

        // 尾数绝杀：如果这个尾数转移从未发生过
        if (tTotal > 20 && tProb < 0.01) {
            score += this.weights.killPenalty / 2; // 尾数杀号惩罚减半，防止误杀
        } else {
            score += tProb * 80 * this.weights.transTail;
        }

        // --- 5. 平特尾数关联 (Flat-Code Correlation) ---
        if (prevFlatNums) {
            const prevTails = prevFlatNums.map(n => n % 10);
            if (prevTails.includes(cTail)) {
                // 只有当历史胜率支持时，才加分
                score += this.flatTailStats.probability * this.weights.flatStrategy;
            }
        }

        // --- 6. 基础频率修正 ---
        score += (this.globalFreq[candidate] / this.history.length) * this.weights.freq;

        return score;
    }

    private sumValues(obj: Record<any, number> | undefined): number {
        if (!obj) return 0;
        return Object.values(obj).reduce((a, b) => a + b, 0);
    }
}

