// 当前(2026马年)的标准生肖排序 (1号=马, 2号=蛇...)
// 用于动态计算历史生肖
const CURRENT_YEAR_SEQ = ['马', '蛇', '龙', '兔', '虎', '牛', '鼠', '猪', '狗', '鸡', '猴', '羊'];
const TARGET_YEAR = 2026; // 设定当前配置对应的年份

/**
 * 根据开奖日期动态修正生肖
 * 解决年份切换导致的历史数据生肖错位问题
 */
export const getZodiacByYear = (num: number, dateStr?: string): string => {
  const defaultZodiac = NUMBER_MAP[num]?.zodiac || '';
  if (!dateStr) return defaultZodiac;

  // 简单提取年份
  let year = parseInt(dateStr.substring(0, 4));
  if (isNaN(year)) return defaultZodiac;

  // 特殊处理：每年的前几期可能属于上一个农历年
  // 这里做一个粗略的修正，假设每年1月固定仍算上一年（虽然不完全准确，但比纯按公历年准）
  const month = parseInt(dateStr.substring(5, 7));
  if (!isNaN(month) && month === 1) {
    year -= 1; 
  }

  // 如果是当前年份或未来，直接返回配置表的数据
  if (year >= TARGET_YEAR) return defaultZodiac;

  // 计算年份偏移量
  // 2026是马(Index 0)
  // 2025是蛇(Index 1) -> 偏移 1
  // 2024是龙(Index 2) -> 偏移 2
  const yearOffset = TARGET_YEAR - year;

  // 基础索引：当前数字在马年序列中的位置 (1号是马=Index 0)
  const baseIndex = (num - 1) % 12;

  // 加上年份偏移
  const finalIndex = (baseIndex + yearOffset) % 12;

  return CURRENT_YEAR_SEQ[finalIndex];
};

